SET
@displaySetId = (SELECT milestone_display_set_id FROM milestone_display_set WHERE display_group = 'THREATMDR_SERVICE_MILESTONE');

UPDATE milestone_display_set_include
SET progress_percentage = 50
WHERE milestone_id = (SELECT milestone_id FROM milestone WHERE milestone_code = 'BULK_ALARM_TUNING_PHASE')
  AND milestone_display_set_id = @displaySetId;

UPDATE milestone_display_set_include
SET progress_percentage = 10
WHERE milestone_id = (SELECT milestone_id FROM milestone WHERE milestone_code = 'EMAIL_USM_TEMPLATE_REQ')
  AND milestone_display_set_id = @displaySetId;
